package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers.
type Matrix interface {
	Rows() [][]int
	Cols() [][]int
	Set(row, col, val int) bool
}

type matrix struct {
	rows [][]int
	cols int
}

// New parses s as a matrix of integers. Rows are separated by newlines and
// elements within a row by whitespace. It returns an error if any row is
// empty, any element is not an integer, or the rows have unequal lengths.
func New(s string) (Matrix, error) {
	lines := strings.Split(s, "\n")
	m := &matrix{}
	for _, line := range lines {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			n, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = n
		}
		if m.cols == 0 {
			m.cols = len(row)
		} else if len(row) != m.cols {
			return nil, errors.New("rows have unequal lengths")
		}
		m.rows = append(m.rows, row)
	}
	return m, nil
}
```

